#include <iostream>
using namespace std;

template <typename T>
void show(T x) {
    cout << "通用那一份" << endl;
}

template <>
void show<const char*>(const char* x) {
    cout << "小灶那一份：" << x << endl;
}

int main() {
    show(7);
    show("大肥鱼");
    return 0;
}

#include <iostream>
using namespace std;

template <typename T>
void pick(T x) {
    cout << "图纸裁出来的那一份" << endl;
}

template <>
void pick<int>(int x) {
    cout << "整数小灶" << endl;
}

void pick(int x) {
    cout << "直接写的那一份" << endl;
}

int main() {
    pick(7);
    pick<>(7);
    pick(2.5);
    return 0;
}
